      const sw = st % 2 ? s.song.swing * sp : 0;
      const t = s.next + sw, I = s.intensity, root = s.song.root;
      const M = this.music;
      // kick / snare / hats
      if (I >= 1) {
        if (st % 4 === 0) { this.tone(150, 0.22, { to: 42, glide: 0.18, gain: 0.5, dest: M, when: t }); }
        if (st === 4 || st === 12) { this.noise(0.16, { f: 1800, gain: 0.22, dest: M, when: t, q: 0.5 }); this.tone(220, 0.08, { to: 140, gain: 0.12, dest: M, when: t }); }
        if (I >= 2 && st % 2 === 1) this.noise(0.04, { ftype: 'highpass', f: 7000, gain: 0.06, dest: M, when: t });
        if (I >= 3 && (st === 14 || st === 15) && bar % 4 === 3) this.noise(0.08, { f: 1400, gain: 0.12, dest: M, when: t });
      }
      // bass on 8ths with a little syncopation
      if ([0, 3, 6, 8, 11, 14].includes(st)) {
        const n = root - 24 + chord[0] + (st === 11 ? 12 : 0);
        this.tone(this.midi(n), sp * 1.6, { type: 'sawtooth', gain: 0.22, lp: 560, lpTo: 260, dest: M, when: t });
      }
