      if (I >= 2 && st % 2 === 0) { const iv = chord[(st / 2) % chord.length]; this.tone(this.midi(root + 12 + iv), sp * 0.9, { type: 'square', gain: 0.045, lp: 2600, dest: M, when: t }); }
