/* ============================================================ art: canvas helpers, rider sprites, item pictures, particles */
const DS = 0.44;                 // rider draw scale: sprite px -> world px (rider ~280 x 170)
const TW = 2048;                 // backdrop tile width in logical px (wider than any view)
const INK = '#241a42';
const FONT_D = '"Mochiy Pop One", "M PLUS Rounded 1c", "Arial Rounded MT Bold", "Trebuchet MS", sans-serif';
const FONT_U = '"M PLUS Rounded 1c", "Arial Rounded MT Bold", system-ui, sans-serif';

function mkCanvas(w, h) { const c = document.createElement('canvas'); c.width = Math.max(1, Math.ceil(w)); c.height = Math.max(1, Math.ceil(h)); return c; }
function rrect(g, x, y, w, h, r) {
  r = Math.max(0, Math.min(r, w / 2, h / 2));
  g.beginPath(); g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r);
  g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath();
}
function hex2rgb(h) { const n = parseInt(h.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function rgba(h, a) { const c = hex2rgb(h); return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')'; }
function mixc(a, b, t) { const A = hex2rgb(a), B = hex2rgb(b); return '#' + A.map((v, i) => Math.round(v + (B[i] - v) * t).toString(16).padStart(2, '0')).join(''); }
function vg(g, y0, y1, stops) { const gr = g.createLinearGradient(0, y0, 0, y1); for (const s of stops) gr.addColorStop(s[0], s[1]); return gr; }
function hg(g, x0, x1, stops) { const gr = g.createLinearGradient(x0, 0, x1, 0); for (const s of stops) gr.addColorStop(s[0], s[1]); return gr; }
function rg(g, x, y, r, stops, r0 = 0) { const gr = g.createRadialGradient(x, y, r0, x, y, r); for (const s of stops) gr.addColorStop(s[0], s[1]); return gr; }
