/* ------------------------------------------------------------ particles + floating text (world coordinates) */
const FX = {
  ps: [], texts: [],
  clear() { this.ps.length = 0; this.texts.length = 0; },
  add(o) {
    if (this.ps.length > 520) this.ps.splice(0, 40);
    const p = { x: 0, y: 0, vx: 0, vy: 0, g: 0, drag: 0, life: 0.6, t: 0, size: 6, grow: 0, color: '#ffffff', kind: 'dot', rot: 0, vr: 0, a: 1, add: false, screen: false };
    for (const k in o) p[k] = o[k];
    this.ps.push(p); return p;
  },
  text(x, y, s, o = {}) {
    if (this.texts.length > 24) this.texts.shift();
    this.texts.push({ x, y, s, t: 0, life: o.life || 0.9, size: o.size || 26, color: o.color || '#fff5e6', vy: o.vy != null ? o.vy : -90, pop: o.pop != null ? o.pop : 1, screen: !!o.screen });
  },
  dust(x, y, n = 6, col = '#f3e9ff', spread = 1) {
    for (let i = 0; i < n; i++) {
      const a = Math.PI + (Math.random() - 0.5) * 1.6 * spread;
      this.add({ kind: 'puff', x: x + (Math.random() - 0.5) * 50 * spread, y: y - 4, vx: Math.cos(a) * (60 + Math.random() * 150) - 140, vy: -20 - Math.random() * 70, drag: 2.2, life: 0.42 + Math.random() * 0.3, size: 12 + Math.random() * 12, grow: 40, color: col, a: 0.55 });
    }
  },
  sparks(x, y, n = 8, cols = ['#ffcf6e', '#fff5e6'], speed = 260, o = {}) {
    for (let i = 0; i < n; i++) {
      const a = Math.random() * TAU, s = speed * (0.4 + Math.random() * 0.8);
      this.add(Object.assign({ kind: 'star4', x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, drag: 3.2, life: 0.35 + Math.random() * 0.35, size: 5 + Math.random() * 6, color: cols[i % cols.length], rot: Math.random() * TAU, vr: (Math.random() - 0.5) * 8 }, o));
    }
  },
  ring(x, y, col = '#ffffff', r = 40, life = 0.35, w = 5) { this.add({ kind: 'ring', x, y, size: r * 0.25, grow: r / life, life, color: col, lw: w }); },
  confetti(x, y, n = 40, o = {}) {
    const cols = ['#ffcf6e', '#b9a2ff', '#ff7280', '#74e2b5', '#fff5e6', '#7b5cf0'];
    for (let i = 0; i < n; i++) {
      const a = -Math.PI / 2 + (Math.random() - 0.5) * (o.spread || 2.2), s = (o.speed || 700) * (0.45 + Math.random() * 0.7);
      this.add({ kind: 'rect', x: x + (Math.random() - 0.5) * (o.w || 30), y, vx: Math.cos(a) * s + (o.vx || 0), vy: Math.sin(a) * s, g: 1100, drag: 1.4, life: 1.4 + Math.random() * 0.8, size: 7 + Math.random() * 6, color: cols[i % cols.length], rot: Math.random() * TAU, vr: (Math.random() - 0.5) * 16, screen: !!o.screen });
    }
  },
  debris(x, y, n, cols, o = {}) {
    for (let i = 0; i < n; i++) {
      const a = -Math.PI / 2 + (Math.random() - 0.5) * 2.4, s = 300 + Math.random() * 520;
      this.add({ kind: 'shard', x: x + (Math.random() - 0.5) * (o.w || 60), y: y + (Math.random() - 0.5) * (o.h || 60), vx: Math.cos(a) * s + (o.vx || 380), vy: Math.sin(a) * s, g: 1900, life: 0.8 + Math.random() * 0.5, size: 7 + Math.random() * 10, color: cols[i % cols.length], rot: Math.random() * TAU, vr: (Math.random() - 0.5) * 18 });
    }
  },
  update(dt) {
    const ps = this.ps;
    for (let i = ps.length - 1; i >= 0; i--) {
      const p = ps[i]; p.t += dt;
      if (p.t >= p.life) { ps[i] = ps[ps.length - 1]; ps.pop(); continue; }
      if (p.drag) { const d = Math.max(0, 1 - p.drag * dt); p.vx *= d; p.vy *= d; }
      p.vy += p.g * dt; p.x += p.vx * dt; p.y += p.vy * dt; p.rot += p.vr * dt; p.size += p.grow * dt;
    }
    for (let i = this.texts.length - 1; i >= 0; i--) {
      const t = this.texts[i]; t.t += dt; t.y += t.vy * dt; t.vy *= Math.max(0, 1 - 2.5 * dt);
      if (t.t >= t.life) this.texts.splice(i, 1);
    }
  },
  // sx(x) maps world x to screen x; the world transform for y is already applied for non-screen particles
  draw(g, camX, layer) {
    const P = Art.pics;
    for (const p of this.ps) {
      if ((p.layer || 0) !== layer) continue;
      const k = p.t / p.life, x = p.screen ? p.x : p.x - camX, y = p.y;
      let a = p.a * (k < 0.75 ? 1 : 1 - (k - 0.75) / 0.25);
      if (a <= 0.01) continue;
      g.globalAlpha = a;
      if (p.add) g.globalCompositeOperation = 'lighter';
      switch (p.kind) {
        case 'puff': { const s = p.size / 32; g.globalAlpha = a * (1 - k); blit(g, p.tint ? p.tint : P.puff, x, y, s); break; }
        case 'glow': { blit(g, P.glow, x, y, p.size / 32); break; }
        case 'glowW': { blit(g, P.glowW, x, y, p.size / 32); break; }
        case 'dot': g.fillStyle = p.color; circle(g, x, y, p.size * (1 - k * 0.5)); g.fill(); break;
        case 'star4': g.fillStyle = p.color; g.save(); g.translate(x, y); g.rotate(p.rot); sparkle4(g, 0, 0, p.size * (1 - k * 0.4)); g.fill(); g.restore(); break;
        case 'ring': g.strokeStyle = p.color; g.lineWidth = (p.lw || 4) * (1 - k); circle(g, x, y, p.size); g.stroke(); break;
        case 'rect': g.fillStyle = p.color; g.save(); g.translate(x, y); g.rotate(p.rot); g.scale(1, Math.cos(p.rot * 1.7)); g.fillRect(-p.size / 2, -p.size / 3, p.size, p.size * 0.66); g.restore(); break;
        case 'shard': g.fillStyle = p.color; g.save(); g.translate(x, y); g.rotate(p.rot); g.beginPath(); g.moveTo(-p.size / 2, -p.size / 3); g.lineTo(p.size / 2, -p.size / 2); g.lineTo(p.size / 3, p.size / 2); g.closePath(); g.fill(); g.lineWidth = 1.5; g.strokeStyle = rgba(INK, 0.6); g.stroke(); g.restore(); break;
        case 'heart': g.fillStyle = p.color; heartPath(g, x, y, p.size); g.fill(); break;
        case 'petal': g.fillStyle = p.color; g.save(); g.translate(x, y); g.rotate(p.rot); ellipse(g, 0, 0, p.size, p.size * 0.5); g.fill(); g.restore(); break;
        case 'bubble': g.strokeStyle = p.color; g.lineWidth = 2; circle(g, x, y, p.size); g.stroke(); g.fillStyle = 'rgba(255,255,255,0.5)'; circle(g, x - p.size * 0.35, y - p.size * 0.35, p.size * 0.25); g.fill(); break;
        case 'streak': { const k2 = p.len || 0.02; g.strokeStyle = p.color; g.lineWidth = p.size; g.lineCap = 'round'; g.beginPath(); g.moveTo(x, y); g.lineTo(x - p.vx * k2, y - p.vy * k2); g.stroke(); break; }
        case 'treat': blit(g, P.treat, x, y, 0.9); break;
        case 'note': g.fillStyle = p.color; g.font = Math.round(p.size) + 'px ' + FONT_D; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(p.ch || '♪', x, y); break;
      }
      if (p.add) g.globalCompositeOperation = 'source-over';
    }
    g.globalAlpha = 1;
  },
  drawTexts(g, camX, screen = false) {
    for (const t of this.texts) {
      if (t.screen !== screen) continue;
      const k = t.t / t.life, pop = t.pop ? (k < 0.15 ? ease.back(k / 0.15) : 1) : 1;
      g.globalAlpha = k < 0.7 ? 1 : 1 - (k - 0.7) / 0.3;
      g.save(); g.translate(t.screen ? t.x : t.x - camX, t.y); g.scale(pop, pop);
      inkText(g, t.s, 0, 0, t.size, t.color, { stroke: Math.max(4, t.size * 0.2), drop: t.size * 0.1 });
      g.restore();
    }
    g.globalAlpha = 1;
  },
};

