    // tutorial: the level's new move goes first, on a clean stage
    if (G.tips.length) {
      const t = G.tips[0];
      const first = { jump: 'hop', duck: 'duck', djump: 'tall', stomp: 'roomba' }[t];
      if (first && pats[first]) return first;
    }
    if (G.hard >= 2 + Math.floor(G.d * 3) || (G.n < 2 && st.mode === 'level')) return 'rest';
    let tot = 0; const ks = Object.keys(pats);
    for (const k of ks) tot += Course.weight(st, k, pats[k]);
    let r = R() * tot;
