      if (st.mode === 'menu') { this.menuPattern(st); continue; }
      if (st.mode !== 'level') G.d = clamp((G.x / PX_PER_M) / 4200, 0, 1) * (st.mods && st.mods.easy ? 0.7 : 1);
      const k = this.pickPattern(st);
      const x = G.x;
      const free = this.P[k](st, x);
