      const space = HB.x1 + v * this.reactT(st) + G.R() * v * 0.32 * (1 - G.d * 0.5);
      if (k !== 'rest' && G.R() < 0.55) this.line(st, free + 20, free + space - 50, 70);
      G.x = Math.max(free + space, x + 120);
