    mode: st.mode, li: st.li, win, score: Math.floor(st.score), treats: st.treats, tn: st.tn, tt: st.treatsTotal, pct,
    stars, nStars: stars.filter(Boolean).length, hits: st.hits, letters: Object.keys(st.letters), gold: st.gold,
    dist: Math.floor(st.x / PX_PER_M), stomps: st.stomps, close: st.close, djumps: st.djumps, jumps: st.jumps, ducks: st.ducks,
    powers: st.powers, bestMult: st.bestMult, smashes: st.smashes, daily: st.daily,
    bossHits: st.bossHits, bossMax: st.boss ? st.boss.maxHp : 0, pctRun: st.len < Infinity ? clamp(st.x / st.len, 0, 1) : 0,
