    g.beginPath(); g.arc(px, py, 21, -Math.PI / 2, -Math.PI / 2 + f * TAU); g.lineWidth = 4.5; g.strokeStyle = POWER_TINT[k]; g.stroke();
    const blink = st.pw[k] < 1.5 && k !== 'shield' && Math.floor(t * 8) % 2;
